body .dashboard-container-rh{
    display: flex;
    background-color:var(--ed-background);
    height:100vh !important;
}


body .dashboard-container-rh .rh-sidebar{
    min-width:330px;
    background:#E9ECEF !important;
    padding:0px;
}

body .dashboard-container-rh .rh-sidebar ul{
  padding:40px 20px !important;
  margin:0px !important;
  list-style: none !important; 
  padding-top:0px !important;
} 

body .dashboard-container-rh .rh-sidebar{
   list-style: none !important;
} 


body .dashboard-container-rh .rh-sidebar ol{
   list-style: none !important;
   margin:0px !important;
   padding:0px !important;
} 


body .dashboard-container-rh .rh-sidebar ol li{
    margin:2px 0px;
    cursor: pointer;
    font-size:14px !important;
    width:max-content;
    padding:7px 5px;
    padding-right:15px;
    border-radius:10px;
    min-width:100px;
}

body .dashboard-container-rh .rh-sidebar ol li a{
  color:var(--ed-dark) !important;
    width:max-content;
}

body .dashboard-container-rh .rh-sidebar h3{
    font-size:16px !important;
    margin-top:20px !important;
}

body .dashboard-container-rh .rh-sidebar ol li svg{
    margin-right:10px;
    width:18px;
    height:18px;
}

body  .rh-sidebar  li.active-menu{
   background-color:var(--ed-white);
   box-shadow:var(--ed-shadow-df);
}

body .rh-sidebar  li.active-menu,
body .rh-sidebar  li.active-menu span,
body .rh-sidebar  li.active-menu a svg,
body .rh-sidebar  li.active-menu a{
    color:var(--ed-purple) !important;
}

body .dashboard-container-rh .dashboard-content-rh{
    display: block;
    height:100vh;
    width:100%;
}

body .dashboard-container-rh .dashboard-content-rh .navbar-rh{
    height:80px;
    width:100%;
    background:var(--ed-white);
    border-bottom:1px solid var(--ed-silver-light);
}


body  .dashboard-pages-rh {
    display: block;
    height:calc(100vh - 80px);
    width: 100%;
    max-height:calc(100vh - 80px);
    position: relative;
    overflow-y: auto;
    background:var(--ed-background-color);
}

body .dashboard-container-rh .rh-sidebar .ed-rh-logo{
  padding:20px;
}

body .dashboard-container-rh .rh-sidebar .ed-rh-logo img {
    max-width:230px;
}

body .dashboard-container-rh #user-menu-dropdown button{
    background-color:transparent !important;
    padding:0px !important;
}

body .dashboard-container-rh .rh-sidebar{ 
    max-height:100vh;
    overflow-y: auto;
}

body .dashboard-container-rh .rh-sidebar::-webkit-scrollbar {
    width:0px;
    background-color: transparent !important;
}


body .dashboard-container-rh .rh-sidebar::-webkit-scrollbar-thumb {
    background: transparent !important; 
}

body .dashboard-container-rh .rh-sidebar{
    background: rgb(219, 219, 219);
}

body .dashboard-container-rh .rh-sidebar .line{
  background:#e1e1e1;
  height:1px;
  width:100%;
  margin:15px 0px;
}