body .player-page{
    min-height:100vh;
    background:var(--ed-dark);
    padding:40px;
} 

.eduall-video-player  .video-container{
    width:100%; 
    position: relative;
    background:black; 
    min-height:500px; 
    max-height:600px;
}

.eduall-video-player  .video-container svg{
      color:var(--ed-white);
      fill:var(--ed-white);
}


.eduall-video-player  .video-container .play-button{
    position: absolute;
    left:0px;
    top:0px;
    z-index:1;
    width:100%;
    height:100%;
    display: flex;
    align-items: center;
    justify-content: center; 
    transition:all 1s ease-in;
    opacity:1;
}

.eduall-video-player .video-container.theater,
.eduall-video-player .video-container.full-screen{
    max-width: initial;
    width:100%; 
    display: flex;
    justify-content: center;
    margin-inline: auto;
}

.eduall-video-player .video-container.theater{
    max-height:90vh;
}

.eduall-video-player .video-container.full-screen{
    max-height:100vh !important;
}

.eduall-video-player .video-container.full-screen video{
    height:100%;
    border:2px solid red;
}


.eduall-video-player video{
    width:100%; 
    height:100%;
    position: relative;
    max-height:600px;
    margin:0px !important;
}

.eduall-video-player .video-controls-container{ 
    bottom: 0px;
    left:0px;
    right:0px;
    z-index:100;
    transition:opacity 150ms ease-in-out;
    opacity:0;
    position: absolute; 
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
}


.eduall-video-player .video-controls-container::before{
    content: "";
    position: absolute;
    bottom:0;
    background: linear-gradient(to top, rgba(0,0,0, .75), transparent);
    width:100%;
    aspect-ratio:6/1;
    pointer-events: none;
    z-index:-1;
}

.eduall-video-player .video-container:hover .video-controls-container,
.eduall-video-player .video-container:focus-within .video-controls-container,
.eduall-video-player .video-container.paused .video-controls-container{
    opacity:1;
}

.eduall-video-player .video-controls-container .controls{
   display: flex;
   gap:.5rem;
   padding:.25rem;
   padding-bottom:20px;
   align-items: center; 
   justify-content: space-between;
   z-index:100;
   position: relative;
}

.eduall-video-player .video-controls-container .controls .item{
      display: flex;
      align-items: center;
}

.eduall-video-player .video-controls-container .controls button{
    background:none;
    border: none;
    color: white;
    padding:0px;
    height:30px;
    width:30px;
    font-size: 1.1rem;
    opacity:.85;
    cursor: pointer;
}

.eduall-video-player .video-controls-container .controls button:hover{
    opacity:1;
}

.eduall-video-player .video-container.paused .pause-icon{
    display: none;
}

.eduall-video-player .video-container:not(.paused) .play-icon{
    display: none;
}


.eduall-video-player .video-container.theater .tall{
    display: none;
}

.eduall-video-player .video-container:not(.theater) .wide{
    display: none;
}



.eduall-video-player .high-icon,
.eduall-video-player .low-icon,
.eduall-video-player .muted-icon{
    display: none;
}


.eduall-video-player .video-container[data-volume-level="high"] .high-icon{
    display: block;
}

.eduall-video-player .video-container[data-volume-level="low"] .low-icon{
    display: block;
}

.eduall-video-player .video-container[data-volume-level="muted"] .muted-icon{
    display: block;
}


.eduall-video-player .volume-container{
    display: flex;
    align-items: center;
}


.eduall-video-player .volume-container .volume-slider{
    width:0px;
    transform-origin: left;
    transform: scaleX(0);
    transition:width 150ms ease-in-out, transform 150ms ease-in-out;
}

.eduall-video-player .volume-container:hover .volume-slider,
.eduall-video-player .volume-slider:focus-within{
    width:100px;
    transform: scaleX(1);
}

body .eduall-video-player  .duration-container{
    display: flex;
    align-items: center; 
    padding:0px !important;  
    color:#fff;
    min-width:100px;
    font-size:13px !important; 
}

body .eduall-video-player  .duration-container div{
      margin:0px 10px;
      font-size:13px !important;
      font-weight:500 !important;
}

.eduall-video-player .video-container.captions .caption-btn{
    border-bottom:3px solid var(--ed-purple);
}


.eduall-video-player .video-controls-container .controls button.wide-btn{
    width:50px;
}


.eduall-video-player .timeline-container{
    height:7px;
    margin-inline: .5rem;
    cursor: pointer;
    display: flex;
    align-items: center;
}

.eduall-video-player .timeline{
    background-color: rgba(100,100,100,.5);
    height:6px;
    width:100%;
    position: relative;
}

.eduall-video-player .timeline-container:hover .timeline{
    height:100%;
}


.eduall-video-player .timeline::before{
    content:"";
    position: absolute;
    left:0;
    top:0;
    bottom: 0;
    right: calc(100% - var(--preview-position) * 100%);
    background: rgb(150,150,150);
    display: none;
}

.eduall-video-player .timeline::after{
    content:"";
    position: absolute;
    left:0;
    top:0;
    bottom: 0;
    right: calc(100% - var(--progress-position) * 100%);
    background: var(--ed-purple);
}

.eduall-video-player .timeline .thumb-indicator{
    --scale:0;
    position: absolute;
    height:200%;
    top: -50%;
    transform: translateX(-50%) scale((var(--scale)));
    left: calc(var(--progress-position) * 100%);
    background-color: var(--ed-purple);
    border-radius:50%;
    transition: transform 150ms ease-in-out;
    aspect-ratio:1/1; 
}

.eduall-video-player .video-container.scrubbimg .timeline::before,
.eduall-video-player .timeline-container:hover .timeline::before{
    display: block;
}

.eduall-video-player .video-container.scrubbimg  .thumb-indicator,
.eduall-video-player .timeline-container:hover .thumb-indicator{
    --scale:1;
}

.eduall-video-player .video-container.scrubbimg  .timeline,
.eduall-video-player .timeline-container:hover .timeline{
    height:100%;
}


.eduall-video-player .timeline .preview-img{
    position: absolute;
    height:80px;
    aspect-ratio: 16/9;
    top: -1rem;
    transform: translate(-50%, -100%);
    left: calc(var(--preview-position) * 100%);
    border-radius:.25rem;
    border:2px solid #fff;
    display: none !important;
}

.eduall-video-player .video-container.scrubbimg .preview-img,
.eduall-video-player  .timeline-container:hover .preview-img{
    display: none !important;
}

.eduall-video-player .thumbnail-img{
   position:absolute;
   top:0;
   left:0;
   right:0;
   bottom:0;
   width:100%;
   height:100%;
   display: none;
}

.eduall-video-player  .video-container.scrubbimg .thumbnail-img{
    display: block;
}


body .eduall-video-player  .play-btn{    
    background: var(--ed-trp-3); 
    width:70px;
    height:70px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    border-radius:100%;
    box-shadow:var(--ed-shadow-df);
    font-size:40px;
    padding:0px !important;
}

body .eduall-video-player .play-btn svg{
    width:30px;
    height:30px;
    margin:0px !important;
}

 
body .eduall-video-player .info-section .playlist-container{
    position: absolute;
    right:20px;
    top:20px; 
    color: var(--ed-white);
    transition:all 1s ease-in;
    opacity:1;
}

body .eduall-video-player .hide{ 
    z-index:-1;
    opacity:0;
    visibility: hidden;
}

body .eduall-video-player .info-section .comming-next h2{
    font-size:18px;
}
 

body .eduall-video-player .info-section .comming-next .next-item-thumb{
      width:180px;
      height:100px;
      border-radius:10px;
      box-shadow:var(--ed-shadow-3);
      overflow: hidden;
      cursor: pointer;
      transition:all 1s ease-in;
}

body .eduall-video-player .info-section .comming-next .next-item-thumb:hover{
      transform: scale(1.09);
}