body .loaderBox .spinnerLoad span::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 15px;
    height: 15px;
    opacity: 0;
    background: var(--white);
    box-shadow: 0 0 10px var(--ed-purple-light),
        0 0 20px var(--ed-purple-light),
        0 0 40px var(--ed-purple-light),
        0 0 60px var(--ed-purple-light),
        0 0 80px var(--ed-purple-light),
        0 0 100px var(--ed-purple-light);
    border-radius: 100%;
    animation: animateLoaderSpan 2s linear infinite;
}

@keyframes animateLoaderSpan {
    0% {
        transform: scale(1);
        opacity: 1;
    }

    80%,
    100% {
        transform: scale(0);
        opacity: 1;
    }
}


body .loaderBox .spinnerLoad span:nth-child(1) {
    transform: rotate(calc(18deg * 1));
}

body .loaderBox .spinnerLoad span:nth-child(1)::before {
    animation-delay: calc(0.1s * 1);
}

body .loaderBox .spinnerLoad span:nth-child(2) {
    transform: rotate(calc(18deg * 2));
}

body .loaderBox .spinnerLoad span:nth-child(2)::before {
