}

body  .ed-id-card{ 
  height:200px;
  background:var(--ed-white);
  border-radius:6px;
  margin:15px;
  overflow: hidden;
  border:1px solid var(--ed-white-smoke);
  box-shadow:var(--ed-shadow-df);
  min-width:350px !important;
  width:350px;
  transition:all 1s ease-in-out;
}

body  .ed-id-card .text,
body  .ed-id-card  .header,
